package pe.metago;
import android.app.*;import android.content.*;import android.os.Build;import java.util.*;import org.json.*;
public class Reminder extends BroadcastReceiver{
static PendingIntent alarm(Context c,int id){return PendingIntent.getBroadcast(c,id,new Intent(c,Reminder.class).putExtra("test",id==3),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
public static long next(Context c){SharedPreferences p=c.getSharedPreferences("meta",0);Calendar t=Calendar.getInstance();t.set(Calendar.HOUR_OF_DAY,p.getInt("hour",20));t.set(Calendar.MINUTE,p.getInt("minute",0));t.set(Calendar.SECOND,0);t.set(Calendar.MILLISECOND,0);if(t.getTimeInMillis()<=System.currentTimeMillis())t.add(Calendar.DAY_OF_YEAR,1);return t.getTimeInMillis();}
public static boolean exact(Context c){return Build.VERSION.SDK_INT<31||c.getSystemService(AlarmManager.class).canScheduleExactAlarms();}
public static void schedule(Context c){SharedPreferences p=c.getSharedPreferences("meta",0);AlarmManager a=c.getSystemService(AlarmManager.class);a.cancel(alarm(c,1));if(!p.contains("hour")||!p.getBoolean("reminderEnabled",true))return;long t=next(c);if(exact(c)){try{a.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,t,alarm(c,1));return;}catch(SecurityException ignored){}}a.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,t,alarm(c,1));}
public static void test(Context c){show(c,true);}
static void show(Context c,boolean test){SharedPreferences p=c.getSharedPreferences("meta",0);NotificationManager n=c.getSystemService(NotificationManager.class);boolean sound=p.getBoolean("reminderSound",true),vib=p.getBoolean("reminderVibration",true);String channel="saving_v3_"+sound+"_"+vib;NotificationChannel ch=new NotificationChannel(channel,"Recordatorios de ahorro",NotificationManager.IMPORTANCE_HIGH);if(!sound)ch.setSound(null,null);ch.enableVibration(vib);n.createNotificationChannel(ch);long a=p.getLong("daily",1500);PendingIntent pi=PendingIntent.getActivity(c,2,new Intent(c,PremiumActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);if(n.areNotificationsEnabled())n.notify(test?3:1,new Notification.Builder(c,channel).setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle(test?"MetaGO · Prueba de recordatorio":"MetaGO · ¡Hora de ahorrar!").setContentText(String.format(Locale.US,"Hoy puedes ahorrar S/ %.2f",a/100.0)).setContentIntent(pi).setAutoCancel(true).build());}
public void onReceive(Context c,Intent i){schedule(c);SharedPreferences p=c.getSharedPreferences("meta",0);if(!p.getBoolean("reminderEnabled",true))return;long today=0,total=0;try{JSONArray arr=new JSONArray(p.getString("entries","[]"));String date=java.time.LocalDate.now().format(java.time.format.DateTimeFormatter.ofPattern("dd/MM/yyyy"));for(int j=0;j<arr.length();j++){JSONObject o=arr.getJSONObject(j);long amount=o.optLong("amount");total+=amount;if(date.equals(o.optString("date")))today+=amount;}}catch(Exception ignored){}if(total>=p.getLong("goal",200000)||today>=p.getLong("daily",1500))return;show(c,false);}
}